        for k in sorted(k1 & k2):
            compare(f'{path}.{k}', obj1[k], obj2[k], depth+1)
    elif isinstance(obj1, list):
        if len(obj1) != len(obj2):
            print(f'{path}: list length {len(obj1)} vs {len(obj2)}')
            # still compare what we can
